    async def get_subscription_filter(
        self,
        subscription_filter_type: str,
        *,
        timeout: Optional[float] = None,
        headers: Optional[Mapping[str, str]] = None,
        client_request_id: Optional[str] = None,
        response_hook: Optional[ConnectorResponseHook] = None,
    ) -> dict[str, Any] | None:
        """
        Get metadata of a filter

        Get metadata of a filter.
        """
        request_url = f"{self._connection_runtime_url}/subscriptionfilterV2"
        query_params = []
        value = str(subscription_filter_type)
        if isinstance(subscription_filter_type, bool):
            value = value.lower()
        query_params.append(f"subscriptionFilterType={quote(value, safe='')}")
        if query_params:
            request_url += '?' + '&'.join(query_params)

        response = await self.http_client.send(
            "GET", request_url, body=None,
            timeout=timeout,
            headers=headers,
            client_request_id=client_request_id,
            response_hook=response_hook,
        )

        if not (200 <= response.status < 300):
            raise ConnectorException(
                "GET",
                request_url,
                response.status,
                response.text,
            )

        if not response.text:
            return None

        return json.loads(response.text)
